    const group = new THREE.Group();

    // Head (sphere)
    const headGeo = new THREE.SphereGeometry(0.25, 16, 16);
    const headMat = new THREE.MeshBasicMaterial({ color: color });
    const head = new THREE.Mesh(headGeo, headMat);
    head.position.set(0, 0.75, 0);
    group.add(head);

