    const torsoMat = new THREE.MeshBasicMaterial({ color: color });
    const torso = new THREE.Mesh(torsoGeo, torsoMat);
    torso.position.set(0, 0.5, 0);
    group.add(torso);

    // Left arm (box)
    const leftArmGeo = new THREE.BoxGeometry(0.12, 0.45, 0.08);
