                                        currentTrip = null;
                                        startTrip();
                                    });
                                });
                            });
                        });
                    });
                });
            });
        });
    });
}

function animate() {
    animationTime += 1 / 60 * speedMultiplier;

    // Update elevator position based on current floor
    const targetFloor = emptyFloor === -1 ? 0 : emptyFloor;
    const targetY = floorY(targetFloor);
    const startY = elevatorCar.position.y;
